#![cfg(feature = "cyclone-v")]
//! End-to-end tests against a checked-in fixture ELF produced by an external
//! toolchain (`arm-none-eabi-ld`, single PT_LOAD at 0xFFFF0000, 0x54 bytes of
//! code). Because the fixture was not generated by this crate, these tests
//! catch shared encoder/decoder mistakes that round-trip tests cannot.
use sidermux_fwtools::families::cyclone_v::GENERIC;
const BOARD: &sidermux_fwtools::BoardProfile = &GENERIC;

use std::path::PathBuf;

use sidermux_fwtools::{
    BootImage, inspect,
    kind::{CheckStatus, ImageKind},
};

fn fixture_elf() -> Vec<u8> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/fixture.elf");
    std::fs::read(&path).unwrap_or_else(|err| panic!("missing fixture {}: {err}", path.display()))
}

fn packed() -> BootImage {
    BootImage::from_elf(BOARD, fixture_elf().as_slice()).unwrap()
}

#[test]
fn fixture_extracts_expected_code() {
    let elf = fixture_elf();
    let image = packed();
    let bytes = image.as_bytes();

    // The fixture payload is 0x54 bytes (prefix, header slot, boot-entry
    // instruction, literal pool): exactly MIN_RAW_LEN + the pool. The
    // completed image is aligned: align_up(0x54 + 4, 16) = 0x60.
    assert_eq!(bytes.len(), 0x60);

    // Extraction contract: the PT_LOAD segment (file offset 0x1000, 0x54
    // bytes, linked at 0xFFFF0000) lands at image offset 0. Verified against
    // the fixture's own bytes, not a re-implementation of the extractor;
    // compared around the embedded header at 0x40..0x4C.
    assert_eq!(&bytes[..0x40], &elf[0x1000..0x1040]);
    assert_eq!(&bytes[0x4C..0x54], &elf[0x104C..0x1054]);

    // `_start: b .` — a branch-to-self at the segment base is 0xEAFFFFFE in
    // little endian.
    assert_eq!(&bytes[..4], &[0xFE, 0xFF, 0xFF, 0xEA]);

    // The boot-entry instruction at 0x4C..0x50 must survive packaging: the
    // aligned tail keeps the CRC (0x5C..0x60) from reaching it.
    assert_eq!(&bytes[0x4C..0x50], &[0xFE, 0xFF, 0xFF, 0xEA]);

    // Alignment padding between the payload and the CRC.
    assert!(bytes[0x54..0x5C].iter().all(|&b| b == 0));

    // Header fields, verified independently: length covers the completed
    // image, checksum is the u16 sum of the first ten header bytes.
    let header = &bytes[0x40..0x4C];
    assert_eq!(&header[..4], b"AS01");
    assert_eq!(header[4], 0); // version
    assert_eq!(header[5], 0); // flags
    let length_words = u16::from_le_bytes([header[6], header[7]]);
    assert_eq!(usize::from(length_words) * 4, bytes.len());
    let checksum = u16::from_le_bytes([header[10], header[11]]);
    assert_eq!(
        usize::from(checksum),
        header[..10].iter().map(|&b| usize::from(b)).sum::<usize>()
    );

    // CRC consistency, sitting in the aligned tail at 0x5C.
    let stored_crc = u32::from_le_bytes(bytes[0x5C..0x60].try_into().unwrap());
    assert_eq!(sidermux_image::crc32_bzip2(&bytes[..0x5C]), stored_crc);
}

#[test]
fn fixture_inspects_as_elf() {
    let report = inspect::inspect_bytes(&fixture_elf(), Default::default()).unwrap();
    assert_eq!(report.input.kind, ImageKind::Elf);

    let elf = report.elf.as_ref().unwrap();
    assert_eq!(elf.machine, elf::abi::EM_ARM);
    assert_eq!(elf.machine_name, "EM_ARM");
    assert_eq!(elf.entry, 0xFFFF_0000);
    assert_eq!(elf.class, "ELF32");
    assert_eq!(elf.endian, "little");
    assert_eq!(elf.segments.len(), 1);
    assert_eq!(elf.segments[0].filesz, 0x54);

    assert!(report.checks.iter().all(|c| c.status != CheckStatus::Fail));
}

#[test]
fn fixture_pack_round_trips_through_every_format() {
    let image = packed();

    // Boot ROM: detectable unambiguously (0x60 bytes is not a slot multiple).
    let report = inspect::inspect_bytes(image.as_bytes(), Default::default()).unwrap();
    assert_eq!(report.input.kind, ImageKind::BootRom);
    let boot = report.bootrom.as_ref().unwrap();
    assert_eq!(boot.crc_status, sidermux_fwtools::kind::CrcStatus::Passed);
    assert!(boot.header.as_cyclone_v().unwrap().header_checksum_ok);

    // Preloader container: four identical, CRC-valid slots.
    let container = image.to_container().unwrap();
    let report = inspect::inspect_bytes(&container, Default::default()).unwrap();
    assert_eq!(report.input.kind, ImageKind::Preloader);
    let mkp = report.preloader.as_ref().unwrap();
    assert_eq!(mkp.slot_count, 4);
    assert_eq!(mkp.identical, Some(true));
    assert!(
        mkp.slots
            .iter()
            .all(|s| s.crc_status == sidermux_fwtools::kind::CrcStatus::Passed)
    );

    // SD image: MBR describes a partition that fits the file, container sits
    // at the partition start, and every check passes.
    let sd = image.to_sd_image().unwrap();
    let report = inspect::inspect_bytes(&sd, Default::default()).unwrap();
    assert_eq!(report.input.kind, ImageKind::SdImage);
    assert!(report.checks.iter().all(|c| c.status != CheckStatus::Fail));
}

#[test]
fn corrupted_sd_reports_failing_checks_without_panicking() {
    let mut sd = packed().to_sd_image().unwrap();
    // Flip a byte inside slot 2's declared region (container starts at 1 MiB,
    // slot 2 at 1 MiB + 128 KiB).
    let offset = 1024 * 1024 + 2 * 65536 + 0x10;
    sd[offset] ^= 0xFF;

    let report = inspect::inspect_bytes(&sd, Default::default()).unwrap();
    assert_eq!(report.input.kind, ImageKind::SdImage);

    let container = report.sd.as_ref().unwrap().boot_partition.as_ref().unwrap();
    assert_eq!(container.container.as_ref().unwrap().identical, Some(false));

    assert!(report.checks.iter().any(|c| c.status == CheckStatus::Fail));
}
